mapper.select:
select count(*)
from transfer_order a left join transfer_order_item b on a.id = b.order_id
where a.from_user_department_id = #{fromDepartmentId}
and a.to_user_department_id = #{toDepartmentId}
and a.from_user_id = #{fromUserId}
and a.to_user_id = #{toUserId}
and a.approval_status = 'PENDING'
and (

        b.asset_id = #{item.assetId}

    )

select id,order_no,from_user_department_name,to_user_department_name,approval_status,created_at from transfer_order
and order_no like CONCAT('%', #{orderNo},'%')
and from_user_name like CONCAT('%', #{fromUserName}, '%')
and from_user_department_name like CONCAT('%', #{fromUserDepartmentName}, '%')
and to_user_name like CONCAT('%', #{toUserName}, '%')
and to_user_department_name like CONCAT('%', #{toUserDepartmentName}, '%')
and approver_name like CONCAT('%', #{approverName}, '%')
and approval_status = #{approvalStatus}
and created_at >= #{startDate}
and created_at <= #{endDate}
